compile.workshop:
variables {
    global:
        0: g
}

rule ("type-mismatched arguments the reference writes unchecked") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Set Global Variable(g, All Living Players(3));
        Set Global Variable(g, All Living Players(Custom String("a")));
        Set Global Variable(g, Count Of(3));
    }
}

